{{-- Shared add/edit dialog. Controls deliberately have no names or nested form. --}}
<dialog id="academic-subject-dialog" x-ref="subjectDialog" class="academic-subject-dialog" aria-modal="true" aria-labelledby="academic-subject-modal-title" aria-describedby="academic-subject-modal-description" @cancel.prevent="requestClose()" @keydown.tab="trapFocus($event)" @keydown.enter="modalEnter($event)">
    <div class="academic-dialog-header">
        <div><h3 id="academic-subject-modal-title" x-text="editIndex === null ? 'Add subject grade' : 'Edit subject grade'"></h3><p class="record-help" id="academic-subject-modal-description">Copy the Registrar values exactly. Apply changes to this form, then save or verify the full academic record.</p></div>
        <button type="button" class="records-button academic-dialog-close" @click="requestClose()" aria-label="Close subject dialog">×</button>
    </div>
    <div class="academic-dialog-body">
        <div class="records-alert" x-show="localErrors.length" x-cloak role="alert" tabindex="-1" x-ref="modalErrors"><strong>Check the subject information.</strong><ul><template x-for="(message, index) in localErrors" :key="index"><li x-text="message"></li></template></ul></div>
        <div class="records-alert" x-show="previousErrors.length" x-cloak role="note"><strong>The previous record save reported these errors.</strong><ul><template x-for="(message, index) in previousErrors" :key="index"><li x-text="message"></li></template></ul><p class="record-help">Correct the subject and save changes here, then submit the full record again for server validation.</p></div>
        <fieldset class="academic-modal-section"><legend>Subject information</legend><div class="academic-modal-grid">
            @foreach(['subject_name' => ['Subject name', 255], 'subject_code' => ['Subject code (if recorded)', 60], 'units' => ['Units', 30]] as $key => [$label, $max])
                <div class="record-field {{ $key === 'subject_name' ? 'academic-modal-wide' : '' }}">
                    <label for="academic-subject-{{ $key }}">{{ $label }}@if($key === 'subject_name') <span class="records-muted">Required</span>@endif</label>
                    <input type="text" id="academic-subject-{{ $key }}" class="record-input" data-subject-field="{{ $key }}" x-model="draft.{{ $key }}" maxlength="{{ $max }}" @if($key === 'subject_name') x-ref="subjectName" aria-required="true" @endif @if($key === 'units') inputmode="decimal" @endif :aria-invalid="fieldErrors('{{ $key }}').length > 0" aria-describedby="academic-error-{{ $key }}" autocomplete="off">
                    <div class="academic-field-error" id="academic-error-{{ $key }}"><template x-for="(message, index) in fieldErrors('{{ $key }}')" :key="index"><p x-text="message"></p></template></div>
                </div>
            @endforeach
        </div></fieldset>
        <fieldset class="academic-modal-section"><legend>Grading periods</legend><p class="record-help">Use percentage decimals from 0 to 100, or INC/DRP marks as reported. Leave unavailable grades blank.</p><div class="academic-modal-grid">
            @foreach(['prelim' => 'Prelim', 'midterm' => 'Midterm', 'semi_final' => 'Semi-Final', 'final' => 'Final'] as $key => $label)
                <div class="record-field"><label for="academic-subject-{{ $key }}">{{ $label }}</label><input type="text" class="record-input" id="academic-subject-{{ $key }}" data-subject-field="{{ $key }}" x-model="draft.{{ $key }}" inputmode="decimal" maxlength="30" :aria-invalid="fieldErrors('{{ $key }}').length > 0" aria-describedby="academic-error-{{ $key }}" autocomplete="off"><div class="academic-field-error" id="academic-error-{{ $key }}"><template x-for="(message, index) in fieldErrors('{{ $key }}')" :key="index"><p x-text="message"></p></template></div></div>
            @endforeach
        </div></fieldset>
        <fieldset class="academic-modal-section"><legend>Additional information</legend><div class="academic-modal-grid">
            <div class="record-field"><label for="academic-subject-average">Reported average (if present)</label><input type="text" class="record-input" id="academic-subject-average" data-subject-field="average" x-model="draft.average" inputmode="decimal" maxlength="30" :aria-invalid="fieldErrors('average').length > 0" aria-describedby="academic-error-average" autocomplete="off"><div class="academic-field-error" id="academic-error-average"><template x-for="(message, index) in fieldErrors('average')" :key="index"><p x-text="message"></p></template></div></div>
            <div class="record-field"><label for="academic-subject-reported_status">Reported subject status</label><select class="record-input" id="academic-subject-reported_status" data-subject-field="reported_status" x-model="draft.reported_status" :aria-invalid="fieldErrors('reported_status').length > 0" aria-describedby="academic-error-reported_status"><option value="regular">No special mark reported</option><option value="inc">Incomplete / INC</option><option value="dropped">Dropped / DRP</option><option value="unverified">Unverified subject</option></select><div class="academic-field-error" id="academic-error-reported_status"><template x-for="(message, index) in fieldErrors('reported_status')" :key="index"><p x-text="message"></p></template></div></div>
            <div class="record-field academic-modal-wide"><label for="academic-subject-remarks">Remarks as recorded</label><textarea class="record-input" id="academic-subject-remarks" data-subject-field="remarks" x-model="draft.remarks" rows="2" maxlength="2000" :aria-invalid="fieldErrors('remarks').length > 0" aria-describedby="academic-error-remarks"></textarea><div class="academic-field-error" id="academic-error-remarks"><template x-for="(message, index) in fieldErrors('remarks')" :key="index"><p x-text="message"></p></template></div></div>
        </div></fieldset>
        <section class="academic-modal-preview" aria-labelledby="academic-calculation-title">
            <h4 id="academic-calculation-title">Calculation preview</h4>
            <dl class="academic-modal-grid" aria-live="polite" aria-atomic="true"><div><dt>Computed average</dt><dd><strong x-text="subject(draft).averageDisplay"></strong><span class="records-muted" x-show="subject(draft).average !== null" x-text="'Unrounded: '+unroundedAverage(draft)"></span></dd></div><div><dt>Computed subject result</dt><dd><span class="records-badge" :class="resultClass(draft)" x-text="subject(draft).result"></span><span class="records-muted" x-show="subject(draft).numericResult && subject(draft).result !== subject(draft).numericResult" x-text="'Numeric result: '+subject(draft).numericResult"></span></dd></div></dl>
            <div aria-live="polite"><template x-for="reason in subject(draft).reasons" :key="reason"><p class="record-help" :class="subject(draft).conflict ? 'academic-field-error' : ''" x-text="reason"></p></template></div>
            <p class="record-help">The existing four-period formula and unrounded 75% threshold apply. Reconciliation, missing grades and special marks remain review flags. The server recalculates when the record is saved.</p>
        </section>
    </div>
    <div class="academic-dialog-footer"><button type="button" class="records-button" @click="requestClose()">Cancel</button><button type="button" class="records-button is-primary" @click="saveSubject()" x-text="editIndex === null ? 'Add subject' : 'Save changes'"></button></div>
</dialog>
<dialog id="academic-subject-confirmation" x-ref="confirmationDialog" class="academic-subject-dialog academic-confirmation-dialog" aria-modal="true" aria-labelledby="academic-confirmation-title" aria-describedby="academic-confirmation-message" @cancel.prevent="cancelConfirmation()" @keydown.tab="trapFocus($event)">
    <div class="academic-dialog-header"><h3 id="academic-confirmation-title" x-text="confirmation === 'remove' ? 'Remove subject' : 'Discard subject changes?'"></h3></div>
    <div class="academic-dialog-body"><p id="academic-confirmation-message" x-text="confirmation === 'remove' ? 'Are you sure you want to remove this subject from the academic record?' : 'Your changes in this dialog have not been applied. Discard them and return to the subject table?'"></p><p class="record-help" x-show="confirmation === 'remove'" x-text="pendingRemoval === null ? '' : rows[pendingRemoval]?.subject_name"></p><p class="record-help" x-show="confirmation === 'remove'">Only this pending form changes. Previous verified academic record revisions remain in history.</p></div>
    <div class="academic-dialog-footer"><button type="button" class="records-button" x-ref="cancelConfirmation" @click="cancelConfirmation()">Cancel</button><button type="button" class="records-button is-primary" @click="confirmAction()" x-text="confirmation === 'remove' ? 'Remove subject' : 'Discard changes'"></button></div>
</dialog>
